#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────────────────
# deploy.sh — one-shot VPS deploy for the blog stack.
#
# What it does (idempotent — safe to re-run):
#   1. installs Docker, nginx, certbot (only if missing)
#   2. adds 2 GB swap (only if there's none) so the build doesn't OOM
#   3. creates .env.production with auto-generated secrets (only if missing)
#   4. builds + starts the app + MariaDB with docker compose
#   5. configures nginx to reverse-proxy the app (with WebSocket support)
#   6. gets a Let's Encrypt certificate and switches the site to HTTPS
#
# Usage (run as root, from the project folder):
#   sudo bash deploy.sh
#
# Non-interactive (skip the prompts):
#   sudo DOMAIN=example.com LE_EMAIL=you@example.com bash deploy.sh
#   # optional: INCLUDE_WWW=0 to NOT request the www subdomain certificate
# ─────────────────────────────────────────────────────────────────────────────
set -euo pipefail

log()  { printf '\n\033[1;36m==> %s\033[0m\n' "$*"; }
warn() { printf '\033[1;33m[!] %s\033[0m\n' "$*"; }
die()  { printf '\033[1;31m[x] %s\033[0m\n' "$*" >&2; exit 1; }

# ── 0. Preconditions ─────────────────────────────────────────────────────────
[ "$(id -u)" -eq 0 ] || die "Please run as root:  sudo bash deploy.sh"
[ -f docker-compose.yml ] || die "Run this from the project folder (docker-compose.yml not found here)."

# Read a value from: existing env var → prompt (falls back to /dev/tty).
ask() { # ask VARNAME "Question" [default]
  local var="$1" q="$2" def="${3:-}" cur ans
  cur="$(eval "printf '%s' \"\${$var:-}\"")"
  if [ -n "$cur" ]; then return 0; fi
  if [ -n "$def" ]; then q="$q [$def]"; fi
  printf '%s: ' "$q" > /dev/tty
  read -r ans < /dev/tty || true
  ans="${ans:-$def}"
  [ -n "$ans" ] || die "$var is required."
  eval "$var=\$ans"
}

INCLUDE_WWW="${INCLUDE_WWW:-1}"
ask DOMAIN   "Your domain (e.g. example.com, no https://)"
ask LE_EMAIL "Email for Let's Encrypt (renewal notices)"

# ── 1. System packages ───────────────────────────────────────────────────────
log "Installing system packages (Docker, nginx, certbot)…"
export DEBIAN_FRONTEND=noninteractive
if ! command -v docker >/dev/null 2>&1; then
  curl -fsSL https://get.docker.com | sh
else
  echo "Docker already installed."
fi
apt-get update -y
apt-get install -y nginx certbot python3-certbot-nginx git openssl

systemctl enable --now docker >/dev/null 2>&1 || true
systemctl enable --now nginx  >/dev/null 2>&1 || true

# ── 2. Swap (build headroom on a small VPS) ──────────────────────────────────
if [ "$(swapon --show | wc -l)" -eq 0 ] && [ ! -f /swapfile ]; then
  log "Adding 2 GB swap…"
  fallocate -l 2G /swapfile || dd if=/dev/zero of=/swapfile bs=1M count=2048
  chmod 600 /swapfile && mkswap /swapfile && swapon /swapfile
  grep -q '/swapfile' /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab
else
  echo "Swap already present — skipping."
fi

# ── 3. .env.production (generate secrets once) ───────────────────────────────
if [ ! -f .env.production ]; then
  log "Creating .env.production with generated secrets…"
  gen() { openssl rand -base64 "${1:-32}" | tr -d '\n/+=' | cut -c1-"${2:-32}"; }
  NEXTAUTH_SECRET="$(openssl rand -base64 48 | tr -d '\n')"
  DB_ROOT_PASSWORD="$(gen 32 32)"
  DB_PASSWORD="$(gen 32 32)"

  cat > .env.production <<EOF
# Generated by deploy.sh on $(date -u +%FT%TZ)
NEXT_PUBLIC_SITE_URL=https://${DOMAIN}
NEXT_PUBLIC_APP_URL=https://${DOMAIN}
NEXTAUTH_URL=https://${DOMAIN}
NEXTAUTH_SECRET=${NEXTAUTH_SECRET}

DB_ROOT_PASSWORD=${DB_ROOT_PASSWORD}
DB_HOST=db
DB_PORT=3306
DB_USER=appuser
DB_PASSWORD=${DB_PASSWORD}
DB_NAME=api
DATABASE_URL="mysql://appuser:${DB_PASSWORD}@db:3306/api"

SITE_DOMAIN_MAP=
DEFAULT_SITE_KEY=blog
ADMIN_HOSTS=

UPLOAD_PROVIDER=local
UPLOAD_MAX_MB=8

SMTP_HOST=smtp.gmail.com
SMTP_PORT=465
SMTP_USER=
SMTP_PASS=
SMTP_FROM="Your Name <you@${DOMAIN}>"
EOF
  chmod 600 .env.production
  echo "Wrote .env.production (chmod 600). GA / SMTP / Cloudinary are set later from the admin dashboard."
else
  echo ".env.production already exists — keeping it."
fi

# ── 4. Build + start the stack ───────────────────────────────────────────────
# docker compose reads ${VAR} substitutions (the db service's passwords) from a
# `.env` file in this folder — NOT from env_file. So mirror .env.production into
# .env, otherwise DB_ROOT_PASSWORD/DB_* are blank and MariaDB refuses to start.
cp -f .env.production .env
log "Building and starting containers (this can take a few minutes)…"
docker compose up -d --build

# ── 5. nginx reverse proxy ───────────────────────────────────────────────────
log "Configuring nginx for ${DOMAIN}…"
SERVER_NAMES="$DOMAIN"
[ "$INCLUDE_WWW" = "1" ] && SERVER_NAMES="$DOMAIN www.$DOMAIN"

cat > /etc/nginx/sites-available/blog.conf <<EOF
server {
    listen 80;
    listen [::]:80;
    server_name ${SERVER_NAMES};

    client_max_body_size 12M;
    gzip on;
    gzip_types text/plain text/css application/json application/javascript application/xml image/svg+xml;
    gzip_min_length 1024;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 300s;
        proxy_cache_bypass \$http_upgrade;
    }
}
EOF

ln -sf /etc/nginx/sites-available/blog.conf /etc/nginx/sites-enabled/blog.conf
rm -f /etc/nginx/sites-enabled/default
nginx -t
systemctl reload nginx

# ── 6. HTTPS via Let's Encrypt ───────────────────────────────────────────────
log "Requesting HTTPS certificate…"
CERT_DOMAINS=(-d "$DOMAIN")
[ "$INCLUDE_WWW" = "1" ] && CERT_DOMAINS+=(-d "www.$DOMAIN")

if certbot --nginx "${CERT_DOMAINS[@]}" --non-interactive --agree-tos -m "$LE_EMAIL" --redirect; then
  HTTPS_OK=1
elif [ "$INCLUDE_WWW" = "1" ] && certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos -m "$LE_EMAIL" --redirect; then
  warn "www subdomain not reachable — issued certificate for ${DOMAIN} only."
  HTTPS_OK=1
else
  HTTPS_OK=0
fi

# ── Done ─────────────────────────────────────────────────────────────────────
echo
if [ "${HTTPS_OK:-0}" = "1" ]; then
  log "Done! Your site is live: https://${DOMAIN}"
else
  warn "App is running, but HTTPS setup failed."
  echo "  Most likely the domain's DNS A record isn't pointing to this server yet."
  echo "  Point ${DOMAIN} (and www) to this VPS IP, then re-run:"
  echo "     sudo certbot --nginx -d ${DOMAIN} -d www.${DOMAIN} --agree-tos -m ${LE_EMAIL} --redirect"
  echo "  Until then the site is reachable over http://${DOMAIN}"
fi
echo
echo "Useful commands:"
echo "  docker compose logs -f app     # app logs"
echo "  docker compose ps              # status"
echo "  docker compose up -d --build   # redeploy after a git pull"
echo
echo "Next: create your admin user / seed (if applicable):"
echo "  docker compose exec app npx prisma db seed"
